import java.io.*;import java.util.*;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());long x = Long.parseLong(st.nextToken());long y = Long.parseLong(st.nextToken());long n = Long.parseLong(br.readLine());long MOD = 1000000007L;long[] f = new long[6];f[0] = ((x % MOD) + MOD) % MOD;f[1] = ((y % MOD) + MOD) % MOD;f[2] = (f[1] - f[0] + MOD) % MOD;f[3] = (MOD - f[0]) % MOD;f[4] = (MOD - f[1]) % MOD;f[5] = (f[0] - f[1] + MOD) % MOD;int index = (int)((n - 1) % 6);System.out.println(f[index]);}}